<script lang="ts">
 import {focusDialog} from '../utils/focusDialog';
 import {untrack} from 'svelte';
 import {X,Check,HardDrive,Cpu,Download,ShieldCheck,SlidersHorizontal,Palette} from '@lucide/svelte';
 import {api,post} from '../services/api';
 import type {Settings as SettingsType} from '../types';
 let {value,models,onclose,onsave,onerror}:{value:SettingsType;models:any[];onclose:()=>void;onsave:(v:SettingsType)=>void;onerror:(e:unknown)=>void}=$props();
 let draft=$state<SettingsType>(untrack(()=>({...value}))),tab=$state('processing'),saving=$state(false),downloading=$state(false),modelList=$state(untrack(()=>models));
 let notice=$state('');
 async function save(){saving=true;try{await api('/settings',{method:'PUT',body:JSON.stringify(draft)});onsave(draft);onclose();}catch(e){onerror(e);}finally{saving=false;}}
 async function download(){try{downloading=true;await post('/models/heron/download',{});notice='Downloading Heron weights. This is the only action here that uses the network.';const poll=setInterval(async()=>{try{const r=await api('/models');if(r.download.status!=='downloading'){clearInterval(poll);downloading=false;modelList=r.models;notice=r.download.error||'Model installed. Enable Heron for new jobs.';}}catch(e){clearInterval(poll);downloading=false;onerror(e);}},1500);}catch(e){downloading=false;onerror(e);}}
 const numeric=[{key:'min_dimension',label:'Minimum source dimension',unit:'px',min:16,max:2000,step:1},{key:'min_area',label:'Minimum page area',unit:'fraction',min:.0001,max:.5,step:.001},{key:'padding',label:'Crop padding',unit:'PDF pt',min:0,max:36,step:.5},{key:'sensitivity',label:'Background sensitivity',unit:'0–1',min:0,max:1,step:.05},{key:'gutter_sensitivity',label:'Gutter sensitivity',unit:'0–1',min:0,max:1,step:.05},{key:'refinement',label:'Boundary refinement',unit:'0–1',min:0,max:1,step:.05},{key:'duplicate_distance',label:'Similar-image hash distance',unit:'0–20',min:0,max:20,step:1}];
</script>
<div class="modal-backdrop"><div class="modal settings-modal" role="dialog" use:focusDialog={onclose} aria-modal="true" aria-label="Application settings" tabindex="-1">
 <div class="modal-head"><div><h2>Application settings</h2><p>Local preferences. Existing jobs keep their processing settings.</p></div><button class="icon-button" onclick={onclose} aria-label="Close settings"><X size={20}/></button></div>
 <div class="settings-layout"><nav class="settings-nav">{#each [{id:'processing',label:'Processing',icon:SlidersHorizontal},{id:'output',label:'Export & storage',icon:HardDrive},{id:'models',label:'AI models',icon:Cpu},{id:'appearance',label:'Appearance',icon:Palette}] as item}<button class:active={tab===item.id} onclick={()=>tab=item.id}><item.icon size={16}/>{item.label}</button>{/each}</nav>
 <div class="settings-body">
 {#if tab==='processing'}
  <h3>Detection defaults</h3><label class="field">Processing mode<select bind:value={draft.mode}><option value="native">Native only</option><option value="fast">Fast</option><option value="balanced">Balanced</option><option value="maximum">Maximum accuracy</option></select></label>
  <p class="help">Balanced adds Heron when installed and enabled. Maximum accuracy adds multiscale analysis and tiled Heron inference. Classification scores are heuristic, not measured accuracy.</p>
  <div class="form-grid">{#each numeric as item}<label class="field">{item.label}<div class="input-unit"><input type="number" bind:value={draft[item.key]} min={item.min} max={item.max} step={item.step}/><span>{item.unit}</span></div></label>{/each}</div>
  <h3>Resource limits</h3><div class="form-grid"><label class="field">Concurrent documents<input type="number" bind:value={draft.workers} min="1" max="4"/></label><label class="field">Memory per worker (MB)<input type="number" bind:value={draft.memory_mb} min="512" max="16384" step="256"/></label><label class="field">Page timeout (seconds)<input type="number" bind:value={draft.page_timeout} min="10" max="600"/></label><label class="field">Maximum decoded pixels<input type="number" bind:value={draft.max_pixels} min="1000000" max="150000000" step="1000000"/></label></div>
  <p class="help">One page at a time per document. A worker that exceeds its memory or time limit is stopped and the page is marked failed.</p>
 {:else if tab==='output'}
  <h3>Image quality</h3><div class="form-grid"><label class="field">Default format<select bind:value={draft.format}><option value="png">PNG · lossless</option><option value="jpg">JPEG</option><option value="original">Original when possible</option></select></label><label class="field">Extraction preference<select bind:value={draft.preference}><option value="auto">Automatic · visible composition</option><option value="source">Complete source image</option><option value="displayed">As displayed · rendered</option></select></label><label class="field">Resolution<select bind:value={draft.resolution}><option value="source">Original source pixels</option><option value="dpi">Limit to target DPI</option></select></label><label class="field">Fallback / target DPI<input type="number" min="72" max="1200" bind:value={draft.dpi}/></label><label class="field">JPEG quality · {draft.jpeg_quality}<input type="range" min="1" max="100" bind:value={draft.jpeg_quality}/></label><label class="field">JPEG transparency background<input type="color" bind:value={draft.jpeg_background}/></label></div>
  <label class="check-field"><input type="checkbox" bind:checked={draft.preserve_metadata}/>Preserve available source metadata</label><label class="check-field"><input type="checkbox" bind:checked={draft.skip_exact_duplicates}/>Skip identical decoded pixels during export</label><label class="check-field"><input type="checkbox" bind:checked={draft.automatic_export}/>Export accepted photographs when processing finishes</label>
  <h3>Local storage</h3><label class="field">Output directory<input bind:value={draft.output_directory} placeholder="Default: project/data/exports"/></label><p class="help">Enter an absolute local folder path. Every export creates a unique subfolder. Documents, checkpoints and temporary previews live in project/data; set PDF_EXTRACTOR_DATA before starting to relocate them.</p>
 {:else if tab==='models'}
  <h3>Optional layout analysis</h3><p class="help">The base application works offline with Native PDF and OpenCV. Heron finds document figures; it does not generate or modify image content.</p>
  {#each modelList as model}<div class="model-card"><div class="row-between"><strong>{model.name}</strong><span class="badge" class:success={model.available}>{model.available?'Installed':model.installed?'Runtime missing':'Not installed'}</span></div><p>{model.size}</p><dl><dt>Backend</dt><dd>{model.backend}</dd><dt>License</dt><dd>{model.license}</dd><dt>Storage</dt><dd class="path">{model.path}</dd>{#if model.version}<dt>Revision</dt><dd class="path">{model.version}</dd>{/if}</dl>{#if !model.dependencies}<div class="notice"><p>Install the optional runtime in Terminal:</p><code>./scripts/install-ai.sh</code><p>Then reopen this panel. Weights are downloaded separately.</p></div>{:else if !model.installed}<button class="primary" onclick={download} disabled={downloading}><Download size={16}/>{downloading?'Downloading…':'Download Heron (~173 MB)'}</button>{/if}</div>{/each}
  {#if notice}<p class="notice">{notice}</p>{/if}<label class="check-field"><input type="checkbox" disabled={!modelList.some(m=>m.available)} bind:checked={draft.ai_enabled}/>Enable Heron for new jobs</label>
  <div class="form-grid"><label class="field">Processing device<select bind:value={draft.device}><option value="auto">Automatic (MPS / CUDA / CPU)</option><option value="cpu">CPU only</option><option value="mps">Apple MPS, with CPU fallback</option><option value="cuda">CUDA, with CPU fallback</option></select></label><label class="field">AI confidence threshold<input type="number" min=".1" max=".95" step=".05" bind:value={draft.ai_threshold}/></label><label class="field">Inference resolution<input type="number" min="512" max="2048" step="128" bind:value={draft.ai_resolution}/></label></div><p class="help">DocLayout-YOLO, PP-DocLayoutV3 and semantic photo classifiers are not installed or enabled. Their dependency stacks have not been validated in this build.</p>
 {:else}
  <h3>Appearance</h3><label class="field">Theme<select bind:value={draft.theme}><option value="dark">Dark</option><option value="light">Light</option><option value="system">Follow system</option></select></label><div class="privacy-card"><ShieldCheck size={28}/><h3>Your documents stay here.</h3><p>Processing, previews and exports run on this computer. No analytics, cloud processing or document uploads to external services.</p></div>
 {/if}
 </div></div><div class="modal-foot"><button onclick={onclose}>Cancel</button><button class="primary" disabled={saving} onclick={save}><Check size={16}/>Save settings</button></div>
</div></div>
